{
  "findings": [
    {
      "check_id": "CKV_GCP_120",
      "title": "Cloud SQL instance has deletion protection disabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'deletion_protection' attribute is explicitly set to false, allowing the database instance to be accidentally or maliciously deleted without safeguards."
    },
    {
      "check_id": "CKV_GCP_119",
      "title": "Cloud SQL instance allows SSL connections but does not require them",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The 'require_ssl' setting in ip_configuration is false, permitting unencrypted connections to the database which exposes data in transit to interception."
    },
    {
      "check_id": "CKV_GCP_118",
      "title": "Cloud SQL instance has public IP enabled with overly permissive authorized networks",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The instance has 'ipv4_enabled = true' and includes an authorized network entry for '0.0.0.0/0', effectively exposing the database to the entire internet."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n  }\n  deletion_protection = true\n}",
  "fix_summary": "Enabled deletion protection by setting 'deletion_protection' to true. Enforced encrypted connections by setting 'require_ssl' to true. Removed the overly permissive '0.0.0.0/0' authorized network entry to restrict access to the internal VPC range only."
}
